mod solution;

fn main() {
    let cases = [
    (r#"[9,3,7,1,8,2]"#, r#"1,2,3,7,8,9"#),
    (r#"[2,2,1]"#, r#"1,2,2"#),
    (r#"
[2,2,1]
"#, r#"1,2,2"#),
    (r#"  
[9,3,7,1,8,2]
  "#, r#"1,2,3,7,8,9"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS quicksort");
}
